"""Round 102: Kris's Painted & polish picks built (doc 54).
  HUD (teal hearts / aurora mana / banners, growing with level) · mana +3 a level · spells ×2 mana, ×3 cool-down, ×2.5 power · status effects ·
  X twice · the steady draw · loot ribbons and speech bubbles · the spirits in the dialogue box · the load lines · monster and boss bars · sky ports
python tests/test_round102.py   (after node build.mjs)"""
import sys, os, json; sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from harness import game
R = os.path.abspath(os.path.join(os.path.dirname(__file__), '..')); res = []
def check(n, ok, info=''):
    res.append(bool(ok)); print(('PASS ' if ok else 'FAIL ') + n + ('' if ok else '  ' + str(info)[:500]))
WS = "game.scene.getScene('World')"
html = open(os.path.join(R, 'index.html'), encoding='utf-8').read()
check('The load screen speaks of the runestones, not the four quadrants', 'The runestones are waking' in html and '1200 × 1200 tiles' not in html)
with game(painted=True, w=1280, h=720) as g:
    g.wait(3000)
    g.js("['ZMSG','ZAIM','ZDRAW'].forEach(k=>window[k].on=true)")
    h = g.js("(()=>{ var h=document.getElementById('zhud'); return {vis:h&&h.style.display, hearts:h.querySelectorAll('.zh-h').length, banners:h.querySelectorAll('.zh-b').length, sp:getComputedStyle(document.getElementById('stats-panel')).display}; })()")
    check('The new HUD: 3 teal hearts for 30 health, 2 banners at level 1, the old bars hidden (%s)' % h, h['vis'] == '' and h['hearts'] == 3 and h['banners'] == 2 and h['sp'] == 'none', h)
    g.js("(()=>{ var ws=%s, ps=ws.playerState; ps.level=12; ps.maxHp=120; ps.hp=95; ps.unlockedSections=[1,2,3]; ws.calcPlayerStats(); })()" % WS); g.wait(400)
    h2 = g.js("(()=>{ var h=document.getElementById('zhud'), q=[].slice.call(h.querySelectorAll('.zh-h i')).map(i=>i.style.width); return {hearts:q.length, part:q[9], banners:h.querySelectorAll('.zh-b').length, mana:%s.playerState.maxMana, w:parseInt(h.querySelector('.zh-mana').style.width)}; })()" % WS)
    check('…they grow: 12 hearts for 120 health (the 10th three-quarters full), 5 banners at level 12, mana 50 + 3 a level = 83 and a longer arc (%s)' % h2, h2['hearts'] == 12 and h2['part'] == '50%' and h2['banners'] == 5 and h2['mana'] == 83 and h2['w'] > 150, h2)
    sp = g.js("[SPELL_DATA.frost_bolt.manaCost,SPELL_DATA.frost_bolt.cooldown,SPELL_DATA.starfall.manaCost,SPELL_DATA.starfall.cooldown,SPELL_DATA.frost_bolt.effect]")
    check('Spells: Frost Bolt 16 mana / 2.5 s, Starfall 68 / 9.6 s; the old slow is replaced by the freeze (%s)' % sp, sp == [16, 2.5, 68, 9.6, 'none'], sp)
    g.js("""(()=>{ var ws=%s, ps=ws.playerState; ps.godMode=true; ps.equip.spell='frost_bolt_tome'; ps.level=12; ps.mana=83;
      var m=ws.worldMonsters.filter(m=>!m.dead).sort((a,b)=>Math.hypot(a.x-ws.player.x,a.y-ws.player.y)-Math.hypot(b.x-ws.player.x,b.y-ws.player.y))[0];
      m.x=ws.wd.spawnX; m.y=ws.wd.spawnY-110; if(m.cont)m.cont.setPosition(m.x,m.y); ws.worldMonsters.forEach(o=>{ if(o!==m&&Math.hypot(o.x-m.x,o.y-m.y)<500){ o.x+=900; if(o.cont)o.cont.x+=900; } }); m.hp=m.maxHp=99999; ws.player.x=m.x; ws.player.y=m.y+200; ws.player.dir='up'; window._m=m; var mx=m.x, my=m.y; window._pin=setInterval(function(){ m.x=mx; m.y=my; if(m.cont)m.cont.setPosition(mx,my); },16); })()""" % WS)
    g.wait(500); g.key('x', 60); g.wait(300)
    a = g.js("({armed:!!ZAIM.cur, mana:Math.round(%s.playerState.mana), at:ZAIM.cur&&[Math.round(ZAIM.cur.x-_m.x),Math.round(ZAIM.cur.y-_m.y),!!ZAIM.cur.mon], pl:[Math.round(%s.player.x-_m.x),Math.round(%s.player.y-_m.y)]})" % (WS,WS,WS))
    check('X once: the rune circle shows, no mana spent (%s)' % a, a['armed'] and a['mana'] >= 83, a)
    g.key('x', 60); g.wait(60)
    b = g.js("""(()=>{ var ws=%s, A=ws._playerProj||[], p=A.filter(x=>x.spellId==='frost_bolt').pop()||A[A.length-1]; var a=p?Math.atan2(p.vy,p.vx):null, want=p?Math.atan2(_m.y-p.y,_m.x-p.x):0; return {armed:!!ZAIM.cur, log:ZAIM.log.slice(-3), spell:p&&p.spellId, seek:!!(p&&p.seek===_m), da:p?Math.abs(Math.atan2(Math.sin(a-want),Math.cos(a-want))):null}; })()""" % WS)
    check('X again: it casts at the circle — the bolt leaves toward the marked foe and homes on it, 16 mana spent (%s)' % b, not b['armed'] and b['spell'] == 'frost_bolt' and b['seek'] and any('83→67' in x for x in b['log']), b)
    g.js("clearInterval(window._pin)")
    t = g.js("""(()=>{ var ws=%s, m=_m; m._zst=null; ZSTAT.apply(ws,m,'fireball',40); var burn=m._zst&&m._zst.burn&&m._zst.burn.max;
      var f={def:{r:10},x:m.x,y:m.y,hp:50,maxHp:50,isBoss:false}; var oe=ZSTAT.els; ZSTAT.els=function(x){ return x===f?['fire']:oe(x); }; ZSTAT.apply(ws,f,'fireball',40); var fireBurn=!!(f._zst&&f._zst.burn&&f._zst.burn.t>0);
      f._zst=null; f._cc=null; ZSTAT.apply(ws,f,'frost_bolt',40); var fireFreeze=f._zst&&f._zst.freeze&&f._zst.freeze.max; ZSTAT.els=oe;
      var B={def:{r:30,boss:true},x:m.x,y:m.y,hp:500,maxHp:500,isBoss:true}; ZSTAT.apply(ws,B,'frost_bolt',40); var bossFrozen=!!(B._zst&&B._zst.freeze), bossChill=!!(B._zst&&B._zst.chill);
      return [burn,fireBurn,fireFreeze,bossFrozen,bossChill]; })()""" % WS)
    check('Status rules: burn 4 s; a fire-type shrugs off burning but is frozen longer (2.5 s); a great boss is never frozen, only chilled (%s)' % t, t[0] == 4 and t[1] is False and t[2] and t[2] > 2 and t[3] is False and t[4] is True, t)
    g.wait(4200)
    gone = g.js("_m._zst?Object.keys(_m._zst).filter(k=>_m._zst[k].t>0):[]")
    check('Every effect runs out (%s)' % gone, 'freeze' not in gone, gone)
    g.js("(()=>{ var ps=%s.playerState; ps.equip.rHand='short_bow'; ps.ammo={arrow_normal:20}; })()" % WS)
    g.page.keyboard.down('Control'); g.wait(950); g.page.keyboard.up('Control'); g.wait(80)
    d = g.js("(()=>{ var A=%s._playerProj||[]; var p=A[A.length-1]; return p?{dmg:p.dmg,z:p._zdraw}:null; })()" % WS)
    g.wait(900); g.page.keyboard.down('Control'); g.wait(40); g.page.keyboard.up('Control'); g.wait(80)
    d2 = g.js("(()=>{ var A=%s._playerProj||[]; var p=A[A.length-1]; return p?{dmg:p.dmg,z:p._zdraw||1}:null; })()" % WS)
    check('Ctrl held 0.95 s: a full draw ×2; a quick tap ×1 (%s · %s)' % (d, d2), d and d['z'] == 2 and d2 and d2['z'] == 1, (d, d2))
    bars = g.ws("ws.worldMonsters.filter(m=>m._zbar&&m._ztr).length")
    check('Monster bars wear the gilt frame and the damage trail (%d)' % bars, bars > 0, bars)
    g.js("showNotif('💰 +50 gold','#ffd700'); showNotif('Not enough gold!','#ff4444'); showNotif('Mira: \"Hello there, hero.\"','#fff')"); g.wait(400)
    m = g.js("({loot:[...document.querySelectorAll('#zloot .zl')].map(d=>d.textContent), top:[...document.querySelectorAll('#notif-area .notif')].map(d=>d.textContent), bub:document.getElementById('zbub').className, bt:document.getElementById('zbub').textContent})")
    check('Loot slides in at the side, warnings stay on top, a short NPC line is a speech bubble (%s)' % m, any('50 gold' in x for x in m['loot']) and 'Not enough gold!' in m['top'] and m['bub'] == 'on' and 'Hello there' in m['bt'], m)
    g.js("(()=>{ var ps=%s.playerState; ps.hp=10; ps.inventory.push('roast_meat'); })()" % WS)
    g.key('/', 50); g.wait(400)
    inv = g.js("(()=>{ var e=document.getElementById('modal-inventory'); return {open:!!e&&getComputedStyle(e).display!=='none'&&e.style.display!=='none', paused:typeof _openOverlays==='function'&&_openOverlays().length>0}; })()")
    check('/ opens the inventory (the game waits) (%s)' % inv, inv['open'] and inv['paused'], inv)
    u = g.js("(()=>{ var ps=%s.playerState, n0=ps.inventory.filter(x=>x==='roast_meat').length, h0=ps.hp; ZINV.pick('roast_meat'); var b=[...document.querySelectorAll('#modal-inventory .ir-equip')].map(x=>x.textContent); ZINV.use('roast_meat'); return {b:b, n:[n0,ps.inventory.filter(x=>x==='roast_meat').length], hp:[h0,ps.hp]}; })()" % WS)
    check('…and food is eaten right there: "Eat now" beside "Put on O", health up, one fewer (%s)' % u, 'Eat now' in u['b'] and u['n'][1] == u['n'][0] - 1 and u['hp'][1] > u['hp'][0], u)
    tb = g.js("(()=>{ ZINV.setFilter('spells'); var a=[...document.querySelectorAll('#modal-inventory .inv-tab-btn span')].map(x=>x.textContent); var sp=document.querySelectorAll('#modal-inventory .zv-foot').length; ZINV.setFilter('magic'); return {tabs:a, f:ZINV.filter, cur:ZPAUSE.cur(), kit:MON_KIT_SRC.shieldwall_dwarves}; })()")
    check('Inventory: Spells and Skills are separate tabs; the old one-tab name lands on Skills (%s)' % tb, 'Spells' in tb['tabs'] and 'Skills' in tb['tabs'] and 'Spells & skills' not in tb['tabs'] and tb['f'] == 'skills', tb)
    fr=[d for d in tb['kit']['def'] if d['name']=='front']
    check('Shield-wall dwarves: blows from the front now get 30 %% through (%s)' % fr, fr and fr[0]['p']['red'] == 0.7, tb['kit'])
    g.key('Escape', 50); g.wait(300)
    sp2 = g.js("""(()=>{ var ws=%s, s=(ws.wd._shrines||[]).find(x=>x.q===1); ZSPIRIT.free(ws,s); var ft=document.getElementById('fairy-talk'); return {dlg:!!(ZDLG.open&&ZDLG.cur), old:!!(ft&&ft.style.display!=='none'&&ft.isConnected), pic:!!document.querySelector('#zdlg .zd-pic canvas'), txt:(document.querySelector('#zdlg .zd-name')||{}).textContent}; })()""" % WS)
    g.wait(1500)
    check('A freed spirit thanks you in the dialogue box, its painted face beside the words (%s)' % sp2, sp2['dlg'] and not sp2['old'] and sp2['pic'], sp2)
    g.js("(()=>{ if(ZDLG.cur){ ZDLG._q=[]; ZDLG.cur.close(); } })()"); g.wait(300)
    sl = g.js("(()=>{ SITE_LAB.thumbs={}; openSiteLab(); document.querySelector('.sl-tab[data-g=\"mage\"]').click(); var a=SITE_LAB.queue.length; closeModal('sitelab'); return new Promise(r=>setTimeout(()=>r({a:a,b:SITE_LAB.queue.length,busy:SITE_LAB.busy}),400)); })()")
    check('Site Lab: thumbnails stop being drawn once it is closed (%s)' % sl, sl['a'] > 3 and sl['b'] == 0 and not sl['busy'], sl)
    g.js("(()=>{ var ws=%s; ws.playerState.unlockedSections=[1,2,3,4]; ws.playerState.skyBriefSeen=false; SKY.noBrief=false; var s=ws.wd.sites.find(x=>x.type==='skyport'&&x.section===1); ws._enterSite(s); })()" % WS)
    g.wait(3000)
    g.js("(()=>{ var b=[...document.querySelectorAll('button')].find(x=>/launch|begin|start|defend|fly/i.test(x.textContent)&&x.offsetParent&&!x.classList.contains('sb-go')); if(b)b.click(); })()")
    g.wait(2500)
    br = g.js("(()=>{ var S=game.scene.getScene('Sky'); var d=document.getElementById('sky-brief'); return {card:!!d, brief:S&&S._brief, waves:S&&S._totalWaves}; })()")
    check('Sky port: a briefing card waits the first time; three waves (%s)' % br, br['card'] and br['brief'] and br['waves'] == 3, br)
    g.key('Space', 50); g.wait(300)
    br2 = g.js("(()=>{ var S=game.scene.getScene('Sky'); return {card:!!document.getElementById('sky-brief'), brief:S._brief, seen:S.ps.skyBriefSeen}; })()")
    check('…Space begins (%s)' % br2, not br2['card'] and not br2['brief'] and br2['seen'], br2)
    g.page.keyboard.down('Space'); g.wait(1500)
    n = g.js("(()=>{ var S=game.scene.getScene('Sky'); return S._shots102=(S._shots102||0); })()")
    shots = g.js("(()=>{ var S=game.scene.getScene('Sky'); return S.bullets.length+S.enemies.filter(e=>e.hp<e.maxHp||e.dead).length; })()")
    g.page.keyboard.up('Space')
    check('Holding Space keeps firing (%d shots or hits in 1.5 s)' % shots, shots >= 4, shots)
    th = g.js("(()=>{ var S=game.scene.getScene('Sky'); var e=S.enemies.find(e=>!e.dead&&e.bx!==undefined); var c=S.bunkers.find(c=>c.hp>0); if(!c)return null; S.bullets.push({x:c.x,y:c.y+4,vx:0,vy:-1,dmg:1,pierce:0,vis:S.add.rectangle(c.x,c.y,2,2,0xffffff)}); return S.bullets.length; })()")
    g.wait(100)
    th2 = g.js("(()=>{ var S=game.scene.getScene('Sky'); return S.bullets.some(b=>b.vy===-1); })()")
    check('Your shots pass through your own clouds', th and th2, (th, th2))
    check('No page errors', not [e for e in g.errs if '404' not in e and 'decode' not in e], g.errs[:3])
print('\n%d/%d passed' % (sum(res), len(res)))
sys.exit(0 if all(res) else 1)
